update public.spell_catalog set
name_ru='Священное пламя', casting_time='1 действие', spell_range='60 футов', area='1 видимое существо', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Спасбросок Ловкости', damage='1к8 излучением при провале',
effect_summary=$$На видимую цель нисходит сияние. Она совершает спасбросок Ловкости и при провале получает 1к8 урона излучением.$$,
upcast='На 5 уровне урон становится 2к8, на 11 — 3к8, на 17 — 4к8.', notes='Половинное укрытие и укрытие на три четверти не дают цели бонуса к этому спасброску.',
author_description=$$Жрец указывает на кого-то, после чего сверху прилетает порция священного света. Укрытие помогает хуже обычного, потому что, судя по всему, божественная бюрократия умеет находить адресата.$$,
author_comment=$$Бог видит тебя даже за ящиком. Жрец, конечно, обязательно сообщит об этом после боя.$$, updated_at=now() where slug='sacred-flame';

update public.spell_catalog set
name_ru='Шилейла', casting_time='1 бонусное действие', spell_range='На себя', area='Дубинка или боевой посох, который вы держите', duration='1 минута', components=array['В','С','М'], material='омела',
check_type='Атаки оружием', damage='Кость урона оружия становится к8; можно наносить силовой или обычный тип урона',
effect_summary=$$Наполняете природной силой дубинку или боевой посох в руке. Для рукопашных атак этим оружием можно использовать характеристику заклинаний вместо Силы для бросков атаки и урона. Кость урона становится к8, а при нанесении урона можно выбрать силовой урон или обычный тип оружия.$$,
upcast='Кость урона становится к10 на 5 уровне, к12 на 11 и 2к6 на 17.', notes='Заклинание заканчивается раньше, если вы накладываете его снова или выпускаете оружие из рук.',
author_description=$$Друид берёт палку и убеждает природу, что это теперь серьёзное оружие. Природа почему-то соглашается. В результате мудрость начинает бить по голове буквально.$$,
author_comment=$$Когда друид говорит «это просто палка», не верь. У них вообще проблемы с тем, чтобы вещи оставались тем, чем были минуту назад.$$, updated_at=now() where slug='shillelagh';

update public.spell_catalog set
name_ru='Электрошок', casting_time='1 действие', spell_range='Касание', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Рукопашная атака заклинанием', damage='1к8 урона электричеством',
effect_summary=$$Совершаете рукопашную атаку заклинанием. При попадании цель получает 1к8 урона электричеством и не может совершать провоцированные атаки до начала своего следующего хода.$$,
upcast='На 5 уровне урон становится 2к8, на 11 — 3к8, на 17 — 4к8.', notes='',
author_description=$$Хватаешь противника и пропускаешь через него электричество. Если всё прошло удачно, он на секунду слишком занят собственными нервами, чтобы ударить тебя, когда ты отходишь.$$,
author_comment=$$Идеальный способ сообщить человеку, что разговор окончен, не отпуская его руку.$$, updated_at=now() where slug='shocking-grasp';

update public.spell_catalog set
name_ru='Чародейский всплеск', casting_time='1 действие', spell_range='120 футов', area='1 существо или объект', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием', damage='1к8 выбранного типа: кислота, холод, огонь, электричество, яд, психический или звук',
effect_summary=$$Метаете чародейскую энергию в цель. При попадании выбираете тип урона из доступных и наносите 1к8. Если на одной из костей этого заклинания выпадает 8, бросаете ещё к8 и добавляете его к урону; это может повторяться.$$,
upcast='Базовый урон становится 2к8 на 5 уровне, 3к8 на 11 и 4к8 на 17.', notes='За одно наложение максимальное число дополнительных к8 от выпавших восьмёрок равно модификатору вашей характеристики заклинаний.',
author_description=$$Чародей кидает в цель сырую магическую энергию и уже по дороге решает, чем именно она будет убивать. Иногда кости начинают взрываться дополнительными к8, потому что даже сама магия чародея не умеет вовремя остановиться.$$,
author_comment=$$Волшебник хотя бы знает, почему заклинание работает. Чародей просто кидает ещё один к8 и улыбается.$$, updated_at=now() where slug='sorcerous-burst';

update public.spell_catalog set
name_ru='Уход за умирающим', casting_time='1 действие', spell_range='15 футов', area='1 существо с 0 HP, которое ещё не умерло', duration='Мгновенно', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Выбираете существо в пределах дистанции, у которого 0 HP и которое ещё живо. Оно становится стабильным.$$,
upcast='Дистанция удваивается на 5 уровне до 30 футов, на 11 до 60 футов и на 17 до 120 футов.', notes='Не восстанавливает HP и не действует на уже мёртвое существо.',
author_description=$$Не лечит. Не поднимает на ноги. Просто убеждает человека перестать умирать прямо сейчас. Звучит скромно, пока рядом не лежит кто-то, кому это очень срочно нужно.$$,
author_comment=$$Жрец скажет, что спас жизнь. Не спорь. У него ещё могут остаться ячейки.$$, updated_at=now() where slug='spare-the-dying';

update public.spell_catalog set
name_ru='Звёздный огонёк', casting_time='1 действие', spell_range='60 футов', area='1 существо или объект', duration='Мгновенно; метка до конца вашего следующего хода', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием', damage='1к8 урона излучением',
effect_summary=$$Запускаете в цель частицу света. При попадании она получает 1к8 урона излучением, до конца вашего следующего хода испускает тусклый свет в радиусе 10 футов и не может пользоваться преимуществами состояния Невидимый.$$,
upcast='На 5 уровне урон становится 2к8, на 11 — 3к8, на 17 — 4к8.', notes='',
author_description=$$Маленькая звёздная искра бьёт цель, а потом заставляет её некоторое время светиться. Особенно неприятно для тех, кто строил весь жизненный план вокруг слова «невидимость».$$,
author_comment=$$Скрытность прекрасна, пока кто-то не приклеит к тебе магическую лампочку.$$, updated_at=now() where slug='starry-wisp';

update public.spell_catalog set
name_ru='Чудотворство', casting_time='1 действие', spell_range='30 футов', area='Небольшой эффект в пределах дистанции', duration='Мгновенно или до 1 минуты', components=array['В'], material=null,
check_type='', damage='',
effect_summary=$$Создаёте одно малое чудо: меняете вид глаз на 1 минуту; делаете голос втрое громче на 1 минуту и получаете преимущество на Запугивание; меняете пламя на 1 минуту; мгновенно распахиваете или захлопываете незапертую дверь или окно; создаёте мгновенный звук; либо вызываете безвредную дрожь земли на 1 минуту.$$,
upcast='', notes='Одновременно может действовать до трёх эффектов этого заклинания с длительностью 1 минута.',
author_description=$$Жрец делает глаза странными, голос громким, двери нервными и землю слегка дрожащей. Всё это называется «малое чудо», потому что настоящие чудеса, видимо, требуют отдельного согласования с начальством.$$,
author_comment=$$Если для убедительности тебе нужны светящиеся глаза и громовой голос, возможно, проповедь была слабой.$$, updated_at=now() where slug='thaumaturgy';

update public.spell_catalog set
name_ru='Меткий удар', casting_time='1 действие', spell_range='На себя', area='1 атака оружием', duration='Мгновенно', components=array['С','М'], material='оружие, которым вы владеете и которое стоит не меньше 1 мм',
check_type='Одна атака оружием как часть заклинания', damage='Обычный урон оружия или излучение; на высоких уровнях добавляется излучение',
effect_summary=$$Как часть заклинания совершаете одну атаку оружием, использованным как материальный компонент. Для броска атаки и урона используете характеристику заклинаний вместо Силы или Ловкости. При нанесении урона можно выбрать излучение или обычный тип урона оружия.$$,
upcast='На 5 уровне атака наносит дополнительно 1к6 излучением, на 11 — 2к6, на 17 — 3к6.', notes='Оружием нужно владеть, и оно должно стоить не меньше 1 медной монеты.',
author_description=$$Магическое озарение подсказывает, куда именно ударить оружием, после чего ты всё равно должен ударить оружием. Очень сложный путь к открытию, которое воины обычно формулируют как «целься лучше».$$,
author_comment=$$Заклинание для мага, который внезапно понял, что у палки есть и немагический конец.$$, updated_at=now() where slug='true-strike';

update public.spell_catalog set
name_ru='Злая насмешка', casting_time='1 действие', spell_range='60 футов', area='1 существо, которое вы видите или слышите', duration='Мгновенно; помеха до конца следующего хода цели', components=array['В'], material=null,
check_type='Спасбросок Мудрости', damage='1к6 психического урона при провале',
effect_summary=$$Обрушиваете на цель оскорбления, усиленные чарами. При провале спасброска Мудрости цель получает 1к6 психического урона и совершает с помехой следующий бросок атаки до конца своего следующего хода.$$,
upcast='На 5 уровне урон становится 2к6, на 11 — 3к6, на 17 — 4к6.', notes='Цель должна быть в пределах дистанции и быть видимой или слышимой вами.',
author_description=$$Бард оскорбляет существо настолько профессионально, что слова начинают причинять физически измеримый психический урон. Потом цель ещё и хуже дерётся, вероятно потому, что пытается понять, почему спор с музыкантом стал боевой механикой.$$,
author_comment=$$Единственный класс, который может убить тебя замечанием о твоей матери. Именно поэтому никто не зовёт их на семейные ужины.$$, updated_at=now() where slug='vicious-mockery';